export type ProposalService = {
  id: string;
  name: string;
  description: string;
  value: number;
};

export type DemoProposal = {
  id: string;
  slug: string;
  clientName: string;
  clientCompany: string;
  title: string;
  scope: string[];
  deadlineDays: number;
  conditions: string[];
  adBudgetSuggestion: number;
  services: ProposalService[];
  validUntil: string;
  status: "draft" | "sent" | "accepted";
};

